"""Build business-facing source traceability from the audited backend inventory."""
import csv
import json
from pathlib import Path

OUT = Path(__file__).resolve().parent
roles = {r["role_code"]: r["permission_keys"] for r in json.loads((OUT / "backend-role-permissions.json").read_text(encoding="utf-8"))}


def write(name, rows):
    (OUT / f"{name}.json").write_text(json.dumps(rows, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    with (OUT / f"{name}.csv").open("w", newline="", encoding="utf-8-sig") as handle:
        writer = csv.DictWriter(handle, fieldnames=list(rows[0]))
        writer.writeheader()
        writer.writerows({k: "; ".join(v) if isinstance(v, list) else v for k, v in row.items()} for row in rows)


