persona_rows = []
for index, (persona, duty_roles, note) in enumerate(personas, 1):
    if persona == "Read-only Executive":
        duty_roles.remove("proposal_requestor")
    unknown = [r for r in duty_roles if r not in roles]
    assert not unknown, unknown
    permissions = sorted({p for role in duty_roles for p in roles[role]})
    if persona == "Read-only Executive":
        assert not any(p.endswith((".create", ".edit", ".decide", ".publish", ".execute")) for p in permissions)
    persona_rows.append({"persona_id": f"P{index:02d}", "persona": persona, "actual_role_codes": duty_roles, "actual_permission_keys": permissions,
                         "assignment_status": "PROPOSED_UAT_DUTY_MAPPING_NOT_DEPLOYED_USER_ASSIGNMENTS", "sod_and_boundary": note,
                         "evidence": "backend/app/modules/enterprise_structure/permissions.py"})
